<script setup lang="ts">
import {useFeedback} from '@starbeacon/shared/composables/useFeedback.ts'
import {ref,shallowRef} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {Select as ASelect,Tag as ATag,Table as ATable} from 'ant-design-vue'
import StatePanel from '@starbeacon/shared/components/StatePanel.vue'
import {formatTime} from '@starbeacon/shared/types.ts'
import IncidentForm from './IncidentForm.vue'
import IncidentDetail from './IncidentDetail.vue'
import {validIncidentRef,incidentStatuses,incidentCategories,incidentSeverities,type IncidentRecord,type IncidentRef,type IncidentInput} from './incident'
import {useIncidents} from './useIncidents'
const message=useFeedback()
const route=useRoute(),router=useRouter(),state=useIncidents()
const {page,pending,error,cursors,selected,detailPending,detailError,history,historyNext,historyPending,historyError,assignees,assigneePending,assigneeError,busy,unconfirmed,actionError,linkedID}=state
const status=ref(''),severity=ref(''),detailOpen=ref(false),editorOpen=ref(false),editing=shallowRef<IncidentRecord|null>(null),draft=shallowRef<IncidentInput|undefined>(),seed=shallowRef<IncidentRef|undefined>()
const columns=[{title:'事件标题',key:'title',ellipsis:true,width:260},{title:'状态',key:'state',width:120},{title:'分类 / 严重度',key:'category',width:180},{title:'责任人',key:'owner',width:170},{title:'建立时间',key:'created',width:190},{title:'操作',key:'actions',width:90}]
function openEditor(record:IncidentRecord|null){if(unconfirmed.value){restoreAttempt();return}editing.value=record;draft.value=undefined;state.clearActionError();detailOpen.value=false;editorOpen.value=true;void state.loadAssignees()}
function restoreAttempt(){const pending=state.pendingInput();if(!pending)return;draft.value=pending.input;editing.value=pending.id&&selected.value?.id===pending.id?selected.value:null;detailOpen.value=false;editorOpen.value=true;void state.loadAssignees()}
function showDetail(id:string){editorOpen.value=false;detailOpen.value=true;void state.select(id)}
async function save(input:IncidentInput){const id=state.pendingInput()?.id??editing.value?.id??'';if(await state.save(id,input)){editorOpen.value=false;seed.value=undefined;draft.value=undefined;message.success(id?'调查记录已提交':'事件已建立');if(route.query.alert_id)void router.replace({path:'/incidents'});detailOpen.value=true}}
async function confirm(){const id=state.pendingInput()?.id??'';if(await state.confirm()){editorOpen.value=false;seed.value=undefined;draft.value=undefined;message.success(id?'调查记录已确认':'事件已确认');if(route.query.alert_id)void router.replace({path:'/incidents'});detailOpen.value=true}}
const initial={event_id:route.query.alert_id,raw_sha256:route.query.sha256}
if(validIncidentRef(initial)){seed.value=initial;openEditor(null)}
</script>
<template>
 <header class="page-header"><div><h1>事件调查</h1><p class="page-description">关联检测事实与人工线索，记录责任分派、调查材料和可复核的结案依据。</p></div><div class="filter-actions"><a-button :loading="pending" @click="state.refresh">刷新</a-button><a-button v-if="unconfirmed" type="primary" @click="restoreAttempt">核对原提交</a-button><a-button v-else type="primary" @click="seed=undefined;openEditor(null)">建立事件</a-button></div></header>
 <a-form :model="{status,severity}" class="panel incident-filters" layout="inline" @finish="state.search(status,severity)"><a-form-item label="调查状态"><a-select v-model:value="status" aria-label="筛选调查状态" class="incident-select" :options="[{value:'',label:'全部状态'},...Object.entries(incidentStatuses).map(([value,label])=>({value,label}))]"/></a-form-item><a-form-item label="严重度"><a-select v-model:value="severity" aria-label="筛选严重度" class="incident-select" :options="[{value:'',label:'全部严重度'},...Object.entries(incidentSeverities).map(([value,label])=>({value,label}))]"/></a-form-item><a-button type="primary" html-type="submit" :loading="pending">查询</a-button><a-button :disabled="pending" @click="status='';severity='';state.search('','')">重置</a-button></a-form>
 <section class="panel"><div class="panel-header"><h2>安全事件</h2><span>当前页 {{page.items.length}} 条</span></div><StatePanel :loading="pending" :error="error" :empty="!page.items.length" description="当前条件下没有安全事件。可关联告警建立调查，或登记人工线索。" @retry="state.refresh"><a-table size="middle" row-key="id" :data-source="page.items" :columns="columns" :pagination="false" :scroll="{x:1010}"><template #bodyCell="{column,record}"><template v-if="column.key==='title'"><a-button type="link" class="incident-title-button" @click="showDetail(record.id)">{{record.spec.title}}</a-button><div class="muted technical">{{record.id}}</div></template><a-tag v-else-if="column.key==='state'" :color="record.spec.status==='closed'?'green':record.spec.status==='investigating'?'blue':'orange'">{{incidentStatuses[record.spec.status as keyof typeof incidentStatuses]}}</a-tag><template v-else-if="column.key==='category'">{{incidentCategories[record.spec.category as keyof typeof incidentCategories]}} · <a-tag :color="record.spec.severity==='critical'?'red':record.spec.severity==='high'?'orange':record.spec.severity==='medium'?'gold':'green'">{{incidentSeverities[record.spec.severity as keyof typeof incidentSeverities]}}</a-tag></template><template v-else-if="column.key==='owner'">{{record.owner_name||'待分派'}}</template><template v-else-if="column.key==='created'">{{formatTime(record.created_at)}}</template><a-button v-else-if="column.key==='actions'" type="link" @click="showDetail(record.id)">查看</a-button></template></a-table></StatePanel><div class="incident-pagination"><a-button :disabled="pending||cursors.length<=1" @click="state.previous">上一页</a-button><span>第 {{cursors.length}} 页</span><a-button :disabled="pending||!page.next_cursor" @click="state.next">下一页</a-button></div></section>
 <IncidentDetail v-if="detailOpen" :record="selected" :pending="detailPending" :error="detailError" :history="history" :history-pending="historyPending" :history-error="historyError" :next="historyNext" @close="detailOpen=false;state.clearSelection()" @edit="openEditor(selected)" @reload="state.reloadDetail" @history="state.loadHistory"/>
 <IncidentForm v-if="editorOpen" :key="(draft?'frozen_':'')+(editing?.id??'create')" :record="editing" :draft="draft" :seed="seed" :assignees="assignees" :assignee-pending="assigneePending" :assignee-error="assigneeError" :busy="busy" :unconfirmed="unconfirmed" :error="actionError" :linked-id="linkedID" @save="save" @confirm="confirm" @close="editorOpen=false" @reload-owners="state.loadAssignees" @existing="showDetail"/>
</template>
<style scoped>.incident-filters{display:flex;gap:var(--related-gap);flex-wrap:wrap;align-items:center;padding:var(--panel-inset);margin-bottom:var(--section-gap)}.incident-filters .ant-form-item{margin:0}.incident-select{min-width:150px}.incident-pagination{display:flex;justify-content:flex-end;align-items:center;gap:var(--related-gap);padding:var(--panel-inset)}.incident-title-button{max-width:100%;padding:0;white-space:normal;text-align:left;height:auto;overflow-wrap:anywhere}.technical{overflow-wrap:anywhere;font-size:11px}@media(max-width:700px){.incident-filters .ant-form-item{flex:1 1 100%;min-width:0}.incident-pagination{flex-wrap:wrap}}</style>
